import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../../../data/services/auth_service.dart';
import '../../providers/app_state.dart';
import '../../widgets/app_drawer.dart';
class SettingsScreen extends StatelessWidget{const SettingsScreen({super.key});@override Widget build(BuildContext context){final app=context.watch<AppState>();return Scaffold(appBar:AppBar(title:const Text('Settings')),drawer:const AppDrawer(),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField(value:app.languageCode,decoration:const InputDecoration(labelText:'Change Language'),items:const [DropdownMenuItem(value:'sw',child:Text('Kiswahili')),DropdownMenuItem(value:'en',child:Text('English'))],onChanged:(v)=>app.setLanguage(v!)),SwitchListTile(title:const Text('Dark Mode'),value:app.darkMode,onChanged:app.toggleDark),ListTile(leading:const Icon(Icons.person),title:const Text('Profile Management'),subtitle:const Text('Update name, phone and role in users collection')),ListTile(leading:const Icon(Icons.lock),title:const Text('Change Password'),onTap:()=>_password(context)),FilledButton.icon(onPressed:()=>context.read<AuthService>().signOut(),icon:const Icon(Icons.logout),label:const Text('Logout'))]));}void _password(BuildContext context){final p=TextEditingController();showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('Change Password'),content:TextField(controller:p,obscureText:true),actions:[FilledButton(onPressed:(){context.read<AuthService>().changePassword(p.text);Navigator.pop(context);},child:const Text('Save'))]));}}
